pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 preBalance) public {
        preBalance = bound(preBalance, 1, type(uint128).max);

        // Give the contract funds NOT counted by depositsCount.
        vm.deal(address(c), preBalance);

        // Owner deposits exactly 1 wei via the payable fallback.
        vm.deal(address(this), 1);
        (bool sent, ) = address(c).call{value: 1}("");
        assertTrue(sent);

        // Owner withdraws everything.
        c.withdrawAll();

        // General rule: after withdrawAll the contract holds no ether.
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}

