import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max);
        // give the test contract some ether so a valid smaller withdrawal is admissible
        vm.deal(address(this), amount);
        // fund the contract with a small deposit via its payable fallback
        (bool sent, ) = address(c).call{value: 1}("");
        assertTrue(sent);
        // amount > balance (balance == 1 wei): reference must revert (transfer fails),
        // mutant deletes the transfer so it succeeds
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "withdraw of more than balance must revert");
    }
}

